0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PA_x*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1]) + PA_y*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + PB_0*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + PB_1*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0])) + QD_0*delta[a0][d1]*delta[c0][c1]*(PA_1*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PA_x*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1]) + PA_y*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + PB_0*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + PB_1*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0])) + QD_1*delta[a0][c0]*delta[c1][d0]*(PA_1*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PA_x*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1]) + PA_y*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + PB_0*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + PB_1*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0])) + QD_1*delta[a0][c1]*delta[c0][d0]*(PA_1*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PA_x*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1]) + PA_y*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + PB_0*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + PB_1*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0])) + QD_1*delta[a0][d0]*delta[c0][c1]*(PA_1*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PA_x*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1]) + PA_y*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1]) + PB_0*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + PB_1*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0]))

