]) + delta[a0][b1]*(delta[a1][c0]*delta[g0][g1] + delta[a1][g0]*delta[c0][g1] + delta[a1][g1]*delta[c0][g0]) + delta[a0][c0]*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + delta[a0][g0]*(delta[a1][b1]*delta[c0][g1] + delta[a1][c0]*delta[b1][g1] + delta[a1][g1]*delta[b1][c0]) + delta[a0][g1]*(delta[a1][b1]*delta[c0][g0] + delta[a1][c0]*delta[b1][g0] + delta[a1][g0]*delta[b1][c0])) + PB_1*(delta[a0][a1]*(delta[b0][c0]*delta[g0][g1] + delta[b0][g0]*delta[c0][g1] + delta[b0][g1]*delta[c0][g0]) + delta[a0][b0]*(delta[a1][c0]*delta[g0][g1] + delta[a1][g0]*delta[c0][g1] + delta[a1][g1]*delta[c0][g0]) + delta[a0][c0]*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0]) + delta[a0][g0]*(delta[a1][b0]*delta[c0][g1] + delta[a1][c0]*delta[b0][g1] + delta[a1][g1]*delta[b0][c0]) + delta[a0][g1]*(delta[a1][b0]*delta[c0][g0] + delta[a1][c0]*delta[b0][g0] + delta[a1][g0]*delta[b0][c0]))))

