[g1] + delta[a0][g0]*delta[c0][g1] + delta[a0][g1]*delta[c0][g0])) + QD_1*(delta[c0][c1]*(delta[a0][d0]*delta[g0][g1] + delta[a0][g0]*delta[d0][g1] + delta[a0][g1]*delta[d0][g0]) + delta[c0][d0]*(delta[a0][c1]*delta[g0][g1] + delta[a0][g0]*delta[c1][g1] + delta[a0][g1]*delta[c1][g0]) + delta[c1][d0]*(delta[a0][c0]*delta[g0][g1] + delta[a0][g0]*delta[c0][g1] + delta[a0][g1]*delta[c0][g0]))) + PA_x*(delta[a0][a1]*(QC_0*(delta[c1][d0]*delta[d1][g1] + delta[c1][d1]*delta[d0][g1] + delta[c1][g1]*delta[d0][d1]) + QC_1*(delta[c0][d0]*delta[d1][g1] + delta[c0][d1]*delta[d0][g1] + delta[c0][g1]*delta[d0][d1]) + QD_0*(delta[c0][c1]*delta[d1][g1] + delta[c0][d1]*delta[c1][g1] + delta[c0][g1]*delta[c1][d1]) + QD_1*(delta[c0][c1]*delta[d0][g1] + delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0])) + delta[a0][g1]*(QC_0*(delta[a1][c1]*delta[d0][d1] + delta[a1][d0]*delta[c1][d1] + delta[a1][d1]*delta[c1][d0]) + QC_1*(delta[a1][c0]*delta[d0][d1] + delta[a1][d0]*delta[c0][d1] + delta[a1][d1]*delta[c0][d0]) + QD_0*(delta[a1][c0]*delta[c1][d1] + delta[a1][c1]*delta[c0][d1] + delta[a1][d1]*delta[c0][c1]) + QD_1*(delta[a1][c0]*delta[c1][d0] + delta[a1][c1]*delta[c0][d0] + delta[a1][d0]*delta[c0][c1])) + delta[a1][g1]*(QC_0*(delta[a0][c1]*delta[d0][d1] + delta[a0][d0]*delta[c1][d1] + delta[a0][d1]*delta[c1][d0]) + QC_1*(delta[a0][c0]*delta[d0][d1] + delta[a0][d0]*delta[c0][d1] + delta[a0][d1]*delta[c0][d0]) + QD_0*(delta[a0][c0]*delta[c1][d1] + delta[a0][c1]*delta[c0][d1] + delta[a0][d1]*delta[c0][c1]) + QD_1*(delta[a0][c0]*delta[c1][d0] + delta[a0][c1]*delta[c0][d0] + delta[a0][d0]*delta[c0][c1]))) + PA_y*(delta[a0][a1]*(QC_0*(delta[c1][d0]*delta[d1][g0] + delta[c1][d1]*delta[d0][g0] + delta[c1][g0]*delta[d0][d1]) + QC_1*(delta[c0][d0]*delta[d1][g0] + delta[c0][d1]*delta[d0][g0] + delta[c0][g0]*delta[d0][d1]) + QD_0*(delta[c0][c1]*delta[d1][g0] + delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1]) + QD_1*(delta[c0][c1]*delta[d0][g0] + delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0])) + delta[a0][g0]*(QC_0*(delta[a1][c1]*delta[d0][d1] + delta[a1][d0]*delta[c1][d1] + delta[a1][d1]*delta[c1][d0]) + QC_1*(delta[a1][c0]*delta[d0][d1] + delta[a1][d0]*delta[c0][d1] + delta[a1][d1]*delta[c0][d0]) + QD_0*(delta[a1][c0]*delta[c1][d1] + delta[a1][c1]*delta[c0][d1] + delta[a1][d1]*delta[c0][c1]) + QD_1*(delta[a1][c0]*delta[c1][d0] + delta[a1][c1]*delta[c0][d0] + delta[a1][d0]*delta[c0][c1])) + delta[a1][g0]*(QC_0*(delta[a0][c1]*delta[d0][d1] + delta[a0][d0]*delta[c1][d1] + delta[a0][d1]*delta[c1][d0]) + QC_1*(delta[a0][c0]*delta[d0][d1] + delta[a0][d0]*delta[c0][d1] + delta[a0][d1]*delta[c0][d0]) + QD_0*(delta[a0][c0]*delta[c1][d1] + delta[a0][c1]*delta[c0][d1] + delta[a0][d1]*delta[c0][c1]) + QD_1*(delta[a0][c0]*delta[c1][d0] + delta[a0][c1]*delta[c0][d0] + delta[a0][d0]*delta[c0][c1]))))

                            -(PQ[c0]*QC_1*delta[d0][d1] + PQ[c0]*QD_0*delta[c1][d1] + PQ[c0]*QD_1*delta[c1][d0] + PQ[c1]*QC_0*delta[d0][d1] + PQ[c1]*QD_0*delta[c0][d1] + PQ[c1]*QD_1*delta[c0][d0] + PQ[d0]*QC_0*delta[c1][d1] + PQ[d0]*QC_1*delta[c0][d1] + PQ[d0]*QD_1*delta[c0][c1] + PQ[d1]*QC_0*delta[c1][d0] + PQ[d1]*QC_1*delta[c0][d0] + PQ[d1]*QD_0*delta[c0][c1] + QC_0*QC_1*delta[d0][d1] + QC_0*QD_0*delta[c1][d1] + QC_0*QD_1*delta[c1][d0] + QC_1*QD_0*delta[c0][d1] + QC_1*QD_1*delta[c0][d0] + QD_0*QD_1*delta[c0][c1])*(PA_0*PA_1*delta[b0][b1]*delta[g0][g1] + PA_0*PA_1*delta[b0][g0]*delta[b1][g1] + PA_0*PA_1*delta[b0][g1]*delta[b1][g0] + PA_0*PA_x*delta[a1][b0]*delta[b1][g1] + PA_0*PA_x*delta[a1][b1]*delta[b0][g1] + PA_0*PA_x*delta[a1][g1]*delta[b0][b1] + PA_0*PA_y*delta[a1][b0]*delta[b1][g0] + PA_0*PA_y*delta[a1][b1]*delta[b0][g0] + PA_0*PA_y*delta[a1][g0]*delta[b0][b1] + PA_0*PB_0*delta[a1][b1]*delta[g0][g1] + PA_0*PB_0*delta[a1][g0]*delta[b1][g1] + PA_0*PB_0*delta[a1][g1]*delta[b1][g0] + PA_0*PB_1*delta[a1][b0]*delta[g0][g1] + PA_0*PB_1*delta[a1][g0]*delta[b0][g1] + PA_0*PB_1*delta[a1][g1]*delta[b0][g0] + PA_1*PA_x*delta[a0][b0]*delta[b1][g1] + PA_1*PA_x*delta[a0][b1]*delta[b0][g1] + PA_1*PA_x*delta[a0][g1]*delta[b0][b1] + PA_1*PA_y*delta[a0][b0]*delta[b1][g0] + PA_1*PA_y*delta[a0][b1]*delta[b0][g0] + PA_1*PA_y*delta[a0][g0]*delta[b0][b1] + PA_1*PB_0*delta[a0][b1]*delta[g0][g1] + PA_1*PB_0*delta[a0][g0]*delta[b1][g1] + PA_1*PB_0*delta[a0][g1]*delta[b1][g0] + PA_1*PB_1*delta[a0][b0]*delta[g0][g1] + PA_1*PB_1*delta[a0][g0]*delta[b0][g1] + PA_1*PB_1*delta[a0][g1]*delta[b0][g0] + PA_x*PA_y*delta[a0][a1]*delta[b0][b1] + PA_x*PA_y*delta[a0][b0]*delta[a1][b1] + PA_x*PA_y*delta[a0][b1]*delta[a1][b0] + PA_x*PB_0*delta[a0][a1]*delta[b1][g1] + PA_x*PB_0*delta[a0][b1]*delta[a1][g1] + PA_x*PB_0*delta[a0][g1]*delta[a1][b1] + PA_x*PB_1*delta[a0][a1]*delta[b0][g1] + PA_x*PB_1*delta[a0][b0]*delta[a1][g1] + PA_x*PB_1*delta[a0][g1]*delta[a1][b0] + PA_y*PB_0*delta[a0][a1]*delta[b1][g0] + PA_y*PB_0*delta[a0][b1]*delta[a1][g0] + PA_y*PB_0*delta[a0][g0]*delta[a1][b1] + PA_y*PB_1*delta[a0][a1]*delta[b0][g0] + PA_y*PB_1*delta[a0][b0]*delta[a1][g0] + PA_y*PB_1*delta[a0][g0]*delta[a1][b0] + PB_0*PB_1*delta[a0][a1]*delta[g0][g1] + PB_0*PB_1*delta[a0][g0]*delta[a1][g1] + PB_0*PB_1*delta[a0][g1]*delta[a1][g0])

                        )


                    );

            ERIs[threadIdx.y][threadIdx.x] -= eri_ijkl * mat_D_full_AO[j_cgto * naos + l_cgto];
