            {
                F10_t[1] *= d2;
            }

            const auto QC_0 = (a_l * inv_S2) * (r_l[c0] - r_k[c0]);
            const auto QC_1 = (a_l * inv_S2) * (r_l[c1] - r_k[c1]);
            const auto QD_0 = (-a_k * inv_S2) * (r_l[d0] - r_k[d0]);
            const auto QD_1 = (-a_k * inv_S2) * (r_l[d1] - r_k[d1]);

            // i-i Hessian

            const double eri_ijkl = Lambda * S_ij_00 * S_kl_00 * (

                        + F10_t[1] * inv_S1 * inv_S4 * a_i * a_i * (

                            +(QC_0*(QC_1*delta[d0][d1] + QD_0*delta[c1][d1] + QD_1*delta[c1][d0]) + QC_1*(QD_0*delta[c0][d1] + QD_1*delta[c0][d0]) + QD_0*QD_1*delta[c0][c1])*(PA_0*(PA_1*(PA_x*(-PA_y*delta[b0][b1] - PB_0*delta[b1][g1] - PB_1*delta[b0][g1] + PQ[b0]*delta[b1][g1] + PQ[b1]*delta[b0][g1] + PQ[g1]*delta[b0][b1]) + PA_y*(PQ[b0]*delta[b1][g0] + PQ[b1]*delta[b0][g0] + PQ[g0]*delta[b0][b1]) + PB_0*(PQ[g0]*delta[b1][g1] + PQ[g1]*delta[b1][g0] + delta[g0][g1]*(-PB_1 + PQ[b1])) + PB_1*(PQ[b0]*delta[g0][g1] + PQ[g0]*delta[b0][g1] + PQ[g1]*delta[b0][g0])) + PA_x*(PB_0*(PQ[a1]*delta[b1][g1] + PQ[b1]*delta[a1][g1] + PQ[g1]*delta[a1][b1]) + PB_1*(PQ[a1]*delta[b0][g1] + PQ[b0]*delta[a1][g1] + PQ[g1]*delta[a1][b0])) + PA_y*(PB_0*(-PA_1*delta[b1][g0] - PA_x*delta[a1][b1] - PB_1*delta[a1][g0] + PQ[a1]*delta[b1][g0] + PQ[b1]*delta[a1][g0] + PQ[g0]*delta[a1][b1]) + PB_1*(PQ[a1]*delta[b0][g0] + PQ[b0]*delta[a1][g0] + PQ[g0]*delta[a1][b0]))) + PA_1*(PA_x*(PB_0*(PQ[a0]*delta[b1][g1] + PQ[b1]*delta[a0][g1] + PQ[g1]*delta[a0][b1]) + PB_1*(PQ[a0]*delta[b0][g1] + PQ[b0]*delta[a0][g1] + PQ[g1]*delta[a0][b0])) + PA_y*(PB_0*(PQ[a0]*delta[b1][g0] + PQ[b1]*delta[a0][g0] + PQ[g0]*delta[a0][b1]) + PB_1*(-PA_0*delta[b0][g0] - PA_x*delta[a0][b0] - PB_0*delta[a0][g0] + PQ[a0]*delta[b0][g0] + PQ[b0]*delta[a0][g0] + PQ[g0]*delta[a0][b0]))) + PA_x*PA_y*(PA_0*(PQ[a1]*delta[b0][b1] + PQ[b0]*delta[a1][b1] + delta[a1][b0]*(-PB_1 + PQ[b1])) + PA_1*(PQ[a0]*delta[b0][b1] + PQ[b1]*delta[a0][b0] + delta[a0][b1]*(-PB_0 + PQ[b0])) + PB_0*(PQ[a0]*delta[a1][b1] + PQ[a1]*delta[a0][b1] + PQ[b1]*delta[a0][a1]) + PB_1*(PQ[a0]*delta[a1][b0] + PQ[a1]*delta[a0][b0] + PQ[b0]*delta[a0][a1])) + PB_0*PB_1*(PA_0*(PQ[a1]*delta[g0][g1] + PQ[g0]*delta[a1][g1] + PQ[g1]*delta[a1][g0]) + PA_1*(PQ[a0]*delta[g0][g1] + PQ[g0]*delta[a0][g1] + PQ[g1]*delta[a0][g0]) + PA_x*(-PA_0*delta[a1][g1] - PA_1*delta[a0][g1] - PA_y*delta[a0][a1] + PQ[a0]*delta[a1][g1] + PQ[a1]*delta[a0][g1] + PQ[g1]*delta[a0][a1]) + PA_y*(PQ[a0]*delta[a1][