1]*delta[c1][g0] + delta[a1][c1]*delta[b1][g0]) + delta[g0][g1]*(delta[a0][a1]*delta[b1][c1] + delta[a0][b1]*delta[a1][c1] + delta[a0][c1]*delta[a1][b1])) + QC_1*(delta[a0][b1]*(delta[a1][g0]*delta[c0][g1] + delta[a1][g1]*delta[c0][g0]) + delta[a0][c0]*(delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + delta[a0][g0]*(delta[a1][b1]*delta[c0][g1] + delta[a1][c0]*delta[b1][g1]) + delta[a0][g1]*(delta[a1][b1]*delta[c0][g0] + delta[a1][c0]*delta[b1][g0]) + delta[g0][g1]*(delta[a0][a1]*delta[b1][c0] + delta[a0][b1]*delta[a1][c0] + delta[a0][c0]*delta[a1][b1]))) + PB_1*(QC_0*(delta[a0][b0]*(delta[a1][g0]*delta[c1][g1] + delta[a1][g1]*delta[c1][g0]) + delta[a0][c1]*(delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0]) + delta[a0][g0]*(delta[a1][b0]*delta[c1][g1] + delta[a1][c1]*delta[b0][g1]) + delta[a0][g1]*(delta[a1][b0]*delta[c1][g0] + delta[a1][c1]*delta[b0][g0]) + delta[g0][g1]*(delta[a0][a1]*delta[b0][c1] + delta[a0][b0]*delta[a1][c1] + delta[a0][c1]*delta[a1][b0])) + QC_1*(delta[a0][b0]*(delta[a1][g0]*delta[c0][g1] + delta[a1][g1]*delta[c0][g0]) + delta[a0][c0]*(delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0]) + delta[a0][g0]*(delta[a1][b0]*delta[c0][g1] + delta[a1][c0]*delta[b0][g1]) + delta[a0][g1]*(delta[a1][b0]*delta[c0][g0] + delta[a1][c0]*delta[b0][g0]) + delta[g0][g1]*(delta[a0][a1]*delta[b0][c0] + delta[a0][b0]*delta[a1][c0] + delta[a0][c0]*delta[a1][b0]))))

                            -2*(delta[a0][g0]*delta[a1][g1] + delta[a0][g1]*delta[a1][g0])*(QC_0*QC_1*(PB_0*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0]) + PB_1*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0])) + QD_0*QD_1*(PB_0*(QC_0*delta[b1][c1] + QC_1*delta[b1][c0]) + PB_1*(QC_0*delta[b0][c1] + QC_1*delta[b0][c0])))

                            -QC_0*QC_1*(PA_x*(QD_0*(delta[a0][g1]*(delta[a1][b0]*delta[b1][d1] + delta[a1][b1]*delta[b0][d1] + delta[a1][d1]*delta[b0][b1]) + delta[a1][g1]*(delta[a0][b0]*delta[b1][d1] + delta[a0][b1]*delta[b0][d1] + delta[a0][d1]*delta[b0][b1])) + QD_1*(delta[a0][g1]*(delta[a1][b0]*delta[b1][d0] + delta[a1][b1]*delta[b0][d0] + delta[a1][d0]*delta[b0][b1]) + delta[a1][g1]*(delta[a0][b0]*delta[b1][d0] + delta[a0][b1]*delta[b0][d0] + delta[a0][d0]*delta[b0][b1]))) + PA_y*(QD_0*(delta[a0][g0]*(delta[a1][b0]*delta[b1][d1] + delta[a1][b1]*delta[b0][d1] + delta[a1][d1]*delta[b0][b1]) + delta[a1][g0]*(delta[a0][b0]*delta[b1][d1] + delta[a0][b1]*delta[b0][d1] + delta[a0][d1]*delta[b0][b1])) + QD_1*(delta[a0][g0]*(delta[a1][b0]*delta[b1][d0] + delta[a1][b1]*delta[b0][d0] + delta[a1][d0]*delta[b0][b1]) + delta[a1][g0]*(delta[a0][b0]*delta[b1][d0] + delta[a0][b1]*delta[b0][d0] + delta[a0][d0]*delta[b0][b1])))) - QD_0*QD_1*(PA_x*(QC_0*(delta[a0][g1]*(delta[a1][b0]*delta[b1][c1] + delta[a1][b1]*delta[b0][c1] + delta[a1][c1]*delta[b0][b1]) + delta[a1][g1]*(delta[a0][b0]*delta[b1][c1] + delta[a0][b1]*delta[b0][c1] + delta[a0][c1]*delta[b0][b1])) + QC_1*(delta[a0][g1]*(delta[a1][b0]*delta[b1][c0] + delta[a1][b1]*delta[b0][c0] + delta[a1][c0]*delta[b0][b1]) + delta[a1][g1]*(delta[a0][b0]*delta[b1][c0] + delta[a0][b1]*delta[b0][c0] + delta[a0][c0]*delta[b0][b1]))) + PA_y*(QC_0*(delta[a0][g0]*(delta[a1][b0]*delta[b1][c1] + delta[a1][b1]*delta[b0][c1] + delta[a1][c1]*delta[b0][b1]) + delta[a1][g0]*(delta[a0][b0]*delta[b1][c1] + delta[a0][b1]*delta[b0][c1] + delta[a0][c1]*delta[b0][b1])) + QC_1*(delta[a0][g0]*(delta[a1][b0]*delta[b1][c0] + delta[a1][b1]*delta[b0][c0] + delta[a1][c0]*delta[b0][b1]) + delta[a1][g0]*(delta[a0][b0]*delta[b1][c0] + delta[a0][b1]*delta[b0][c0] + delta[a0][c0]*delta[b0][b1]))))

                            +(QC_0*QD_1*(PQ[c1]*QD_0 + PQ[d0]*QC_1) + QC_1*QD_0*(PQ[c0]*QD_1 + PQ[d1]*QC_0))*(delta[a0][b0]*(delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + delta[a0][b1]*(delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0]) + delta[a0][g0]*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1]) + delta[a0][g1]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0]) + delta[g0][g1]*(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0]))

