*delta[c1][g0]) + delta[a1][b1]*(delta[b0][c1]*delta[g0][g1] + delta[b0][g0]*delta[c1][g1] + delta[b0][g1]*delta[c1][g0]) + delta[a1][c1]*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + delta[a1][g0]*(delta[b0][b1]*delta[c1][g1] + delta[b0][c1]*delta[b1][g1] + delta[b0][g1]*delta[b1][c1]) + delta[a1][g1]*(delta[b0][b1]*delta[c1][g0] + delta[b0][c1]*delta[b1][g0] + delta[b0][g0]*delta[b1][c1])) + delta[a0][c1]*(delta[a1][b0]*(delta[b1][c0]*delta[g0][g1] + delta[b1][g0]*delta[c0][g1] + delta[b1][g1]*delta[c0][g0]) + delta[a1][b1]*(delta[b0][c0]*delta[g0][g1] + delta[b0][g0]*delta[c0][g1] + delta[b0][g1]*delta[c0][g0]) + delta[a1][g0]*(delta[b0][b1]*delta[c0][g1] + delta[b0][c0]*delta[b1][g1] + delta[b0][g1]*delta[b1][c0]) + delta[a1][g1]*(delta[b0][b1]*delta[c0][g0] + delta[b0][c0]*delta[b1][g0] + delta[b0][g0]*delta[b1][c0])) + delta[a0][g0]*(delta[a1][b1]*(delta[b0][c0]*delta[c1][g1] + delta[b0][c1]*delta[c0][g1]) + delta[a1][c1]*(delta[b0][b1]*delta[c0][g1] + delta[b0][c0]*delta[b1][g1]) + delta[b1][c0]*(delta[a1][b0]*delta[c1][g1] + delta[a1][c1]*delta[b0][g1] + delta[a1][g1]*delta[b0][c1]) + delta[b1][c1]*(delta[a1][b0]*delta[c0][g1] + delta[a1][c0]*delta[b0][g1] + delta[a1][g1]*delta[b0][c0])) + delta[a0][g1]*(delta[a1][b1]*(delta[b0][c0]*delta[c1][g0] + delta[b0][c1]*delta[c0][g0]) + delta[a1][c1]*(delta[b0][b1]*delta[c0][g0] + delta[b0][c0]*delta[b1][g0]) + delta[b1][c0]*(delta[a1][b0]*delta[c1][g0] + delta[a1][c1]*delta[b0][g0] + delta[a1][g0]*delta[b0][c1]) + delta[b1][c1]*(delta[a1][b0]*delta[c0][g0] + delta[a1][c0]*delta[b0][g0] + delta[a1][g0]*delta[b0][c0])) + delta[a1][c0]*(delta[a0][b0]*(delta[b1][c1]*delta[g0][g1] + delta[b1][g0]*delta[c1][g1] + delta[b1][g1]*delta[c1][g0]) + delta[a0][b1]*(delta[b0][c1]*delta[g0][g1] + delta[b0][g0]*delta[c1][g1] + delta[b0][g1]*delta[c1][g0]) + delta[a0][c1]*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + delta[a0][g0]*(delta[b0][b1]*delta[c1][g1] + delta[b0][c1]*delta[b1][g1]) + delta[a0][g1]*(delta[b0][b1]*delta[c1][g0] + delta[b0][c1]*delta[b1][g0])))

                            +(delta[c0][c1]*delta[d0][d1] + delta[c0][d0]*delta[c1][d1] + delta[c0][d1]*delta[c1][d0])*(PQ[a0]*(PQ[a1]*(delta[b0][b1]*delta[g0][g1] + delta[b0][g0]*delta[b1][g1] + delta[b0][g1]*delta[b1][g0]) + PQ[b0]*(delta[a1][b1]*delta[g0][g1] + delta[a1][g0]*delta[b1][g1] + delta[a1][g1]*delta[b1][g0]) + PQ[b1]*(delta[a1][b0]*delta[g0][g1] + delta[a1][g0]*delta[b0][g1] + delta[a1][g1]*delta[b0][g0]) + PQ[g0]*(delta[a1][b0]*delta[b1][g1] + delta[a1][b1]*delta[b0][g1] + delta[a1][g1]*delta[b0][b1]) + PQ[g1]*(delta[a1][b0]*delta[b1][g0] + delta[a1][b1]*delta[b0][g0] + delta[a1][g0]*delta[b0][b1])) + PQ[a1]*(PQ[b0]*(delta[a0][b1]*delta[g0][g1] + delta[a0][g0]*delta[b1][g1] + delta[a0][g1]*delta[b1][g0]) + PQ[b1]*(delta[a0][b0]*delta[g0][g1] + delta[a0][g0]*delta[b0][g1] + delta[a0][g1]*delta[b0][g0]) + PQ[g0]*(delta[a0][b0]*delta[b1][g1] + delta[a0][b1]*delta[b0][g1] + delta[a0][g1]*delta[b0][b1]) + PQ[g1]*(delta[a0][b0]*delta[b1][g0] + delta[a0][b1]*delta[b0][g0] + delta[a0][g0]*delta[b0][b1])) + PQ[b0]*(PQ[b1]*(delta[a0][a1]*delta[g0][g1] + delta[a0][g0]*delta[a1][g1] + delta[a0][g1]*delta[a1][g0]) + PQ[g0]*(delta[a0][a1]*delta[b1][g1] + delta[a0][b1]*delta[a1][g1] + delta[a0][g1]*delta[a1][b1]) + PQ[g1]*(delta[a0][a1]*delta[b1][g0] + delta[a0][b1]*delta[a1][g0] + delta[a0][g0]*delta[a1][b1])) + PQ[b1]*(PQ[g0]*(delta[a0][a1]*delta[b0][g1] + delta[a0][b0]*delta[a1][g1] + delta[a0][g1]*delta[a1][b0]) + PQ[g1]*(delta[a0][a1]*delta[b0][g0] + delta[a0][b0]*delta[a1][g0] + delta[a0][g0]*delta[a1][b0])) + PQ[g0]*PQ[g1]*(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0]))

