                            +PA_0*(PA_1*(PA_x*(PQ[c0]*(PA_y*(PQ[c1]*(delta[b0][d0]*delta[b1][d1] + delta[b0][d1]*delta[b1][d0]) + PQ[d0]*(delta[b0][c1]*delta[b1][d1] + delta[b0][d1]*delta[b1][c1]) + PQ[d1]*(delta[b0][c1]*delta[b1][d0] + delta[b0][d0]*delta[b1][c1])) + PB_0*(PQ[c1]*(delta[b1][d0]*delta[d1][g1] + delta[b1][d1]*delta[d0][g1]) + PQ[d0]*(delta[b1][c1]*delta[d1][g1] + delta[b1][d1]*delta[c1][g1]) + PQ[d1]*(delta[b1][c1]*delta[d0][g1] + delta[b1][d0]*delta[c1][g1])) + PB_1*(PQ[c1]*(delta[b0][d0]*delta[d1][g1] + delta[b0][d1]*delta[d0][g1]) + PQ[d0]*(delta[b0][c1]*delta[d1][g1] + delta[b0][d1]*delta[c1][g1]) + PQ[d1]*(delta[b0][c1]*delta[d0][g1] + delta[b0][d0]*delta[c1][g1]))) + PQ[c1]*(PQ[d0]*(PA_y*(delta[b0][c0]*delta[b1][d1] + delta[b0][d1]*delta[b1][c0]) + PB_0*(delta[b1][c0]*delta[d1][g1] + delta[b1][d1]*delta[c0][g1]) + PB_1*(delta[b0][c0]*delta[d1][g1] + delta[b0][d1]*delta[c0][g1])) + PQ[d1]*(PA_y*(delta[b0][c0]*delta[b1][d0] + delta[b0][d0]*delta[b1][c0]) + PB_0*(delta[b1][c0]*delta[d0][g1] + delta[b1][d0]*delta[c0][g1]) + PB_1*(delta[b0][c0]*delta[d0][g1] + delta[b0][d0]*delta[c0][g1]))) + PQ[d0]*PQ[d1]*(PA_y*(delta[b0][c0]*delta[b1][c1] + delta[b0][c1]*delta[b1][c0]) + PB_0*(delta[b1][c0]*delta[c1][g1] + delta[b1][c1]*delta[c0][g1]) + PB_1*(delta[b0][c0]*delta[c1][g1] + delta[b0][c1]*delta[c0][g1]))) + PB_0*PB_1*(PQ[c0]*(PQ[c1]*(delta[d0][g0]*delta[d1][g1] + delta[d0][g1]*delta[d1][g0]) + PQ[d0]*(delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + PQ[d1]*(delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0])) + PQ[c1]*(PQ[d0]*(delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0]) + PQ[d1]*(delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0])) + PQ[d0]*PQ[d1]*(delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0]))) + PA_y*(PA_x*PB_1*(PQ[c0]*(PQ[c1]*(delta[a1][d0]*delta[b0][d1] + delta[a1][d1]*delta[b0][d0]) + PQ[d0]*(delta[a1][c1]*delta[b0][d1] + delta[a1][d1]*delta[b0][c1]) + PQ[d1]*(delta[a1][c1]*delta[b0][d0] + de