]*(PA_0*(PQ[b0]*(QC_0*delta[c1][g0] + QC_1*delta[c0][g0]) + PQ[g0]*(QC_0*delta[b0][c1] + QC_1*delta[b0][c0])) + PA_x*(PQ[a0]*(QC_0*delta[b0][c1] + QC_1*delta[b0][c0]) + PQ[b0]*(QC_0*delta[a0][c1] + QC_1*delta[a0][c0])) + PB_0*(PQ[a0]*(QC_0*delta[c1][g0] + QC_1*delta[c0][g0]) + PQ[g0]*(QC_0*delta[a0][c1] + QC_1*delta[a0][c0]))))) + PA_x*PB_0*PB_1*(PA_0*(PQ[a1]*(PQ[c0]*(PQ[c1]*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1]) + PQ[d0]*(QC_1*delta[d1][g1] + QD_1*delta[c1][g1]) + PQ[d1]*(QC_1*delta[d0][g1] + QD_0*delta[c1][g1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[d1][g1] + QD_1*delta[c0][g1]) + PQ[d1]*(QC_0*delta[d0][g1] + QD_0*delta[c0][g1]))) + PQ[g1]*(PQ[c0]*(PQ[c1]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + PQ[d0]*(QC_1*delta[a1][d1] + QD_1*delta[a1][c1]) + PQ[d1]*(QC_1*delta[a1][d0] + QD_0*delta[a1][c1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[a1][d1] + QD_1*delta[a1][c0]) + PQ[d1]*(QC_0*delta[a1][d0] + QD_0*delta[a1][c0])))) + PA_1*(PQ[a0]*(PQ[c0]*(PQ[c1]*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1]) + PQ[d0]*(QC_1*delta[d1][g1] + QD_1*delta[c1][g1]) + PQ[d1]*(QC_1*delta[d0][g1] + QD_0*delta[c1][g1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[d1][g1] + QD_1*delta[c0][g1]) + PQ[d1]*(QC_0*delta[d0][g1] + QD_0*delta[c0][g1]))) + PQ[g1]*(PQ[c0]*(PQ[c1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + PQ[d0]*(QC_1*delta[a0][d1] + QD_1*delta[a0][c1]) + PQ[d1]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[a0][d1] + QD_1*delta[a0][c0]) + PQ[d1]*(QC_0*delta[a0][d0] + QD_0*delta[a0][c0])))) + PA_y*(PQ[a0]*(PQ[c0]*(PQ[c1]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + PQ[d0]*(QC_1*delta[a1][d1] + QD_1*delta[a1][c1]) + PQ[d1]*(QC_1*delta[a1][d0] + QD_0*delta[a1][c1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[a1][d1] + QD_1*delta[a1][c0]) + PQ[d1]*(QC_0*delta[a1][d0] + QD_0*delta[a1][c0]))) + PQ[a1]*(PQ[c0]*(PQ[c1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + PQ[d0]*(QC_1*delta[a0][d1] + QD_1*delta[a0][c1]) + PQ[d1]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[a0][d1] + QD_1*delta[a0][c0]) + PQ[d1]*(QC_0*delta[a0][d0] + QD_0*delta[a0][c0])))) + PQ[d0]*PQ[d1]*(PA_0*(PQ[a1]*(QC_0*delta[c1][g1] + QC_1*delta[c0][g1]) + PQ[g1]*(QC_0*delta[a1][c1] + QC_1*delta[a1][c0])) + PA_1*(PQ[a0]*(QC_0*delta[c1][g1] + QC_1*delta[c0][g1]) + PQ[g1]*(QC_0*delta[a0][c1] + QC_1*delta[a0][c0])) + PA_y*(PQ[a0]*(QC_0*delta[a1][c1] + QC_1*delta[a1][c0]) + PQ[a1]*(QC_0*delta[a0][c1] + QC_1*delta[a0][c0]))))

