a0]*PQ[a1]*PQ[d1] + PB_0*PQ[a0]*PQ[a1]*QD_1 - PQ[a0]*PQ[a1]*PQ[b0]*PQ[d1] - PQ[a0]*PQ[a1]*PQ[b0]*QD_1)*(delta[b1][c0]*delta[c1][d0]*delta[g0][g1] + delta[b1][c1]*delta[c0][d0]*delta[g0][g1] + delta[b1][d0]*delta[c0][c1]*delta[g0][g1] + delta[b1][g0]*delta[c0][c1]*delta[d0][g1] + delta[b1][g0]*delta[c0][d0]*delta[c1][g1] + delta[b1][g0]*delta[c0][g1]*delta[c1][d0] + delta[b1][g1]*delta[c0][c1]*delta[d0][g0] + delta[b1][g1]*delta[c0][d0]*delta[c1][g0] + delta[b1][g1]*delta[c0][g0]*delta[c1][d0]) + (PA_0*PQ[a1]*PQ[b1]*PQ[c0] + PA_0*PQ[a1]*PQ[b1]*QC_0 + PA_1*PQ[a0]*PQ[b1]*PQ[c0] + PA_1*PQ[a0]*PQ[b1]*QC_0 + PB_1*PQ[a0]*PQ[a1]*PQ[c0] + PB_1*PQ[a0]*PQ[a1]*QC_0 - PQ[a0]*PQ[a1]*PQ[b1]*PQ[c0] - PQ[a0]*PQ[a1]*PQ[b1]*QC_0)*(delta[b0][c1]*delta[d0][d1]*delta[g0][g1] + delta[b0][d0]*delta[c1][d1]*delta[g0][g1] + delta[b0][d1]*delta[c1][d0]*delta[g0][g1] + delta[b0][g0]*delta[c1][d0]*delta[d1][g1] + delta[b0][g0]*delta[c1][d1]*delta[d0][g1] + delta[b0][g0]*delta[c1][g1]*delta[d0][d1] + delta[b0][g1]*delta[c1][d0]*delta[d1][g0] + delta[b0][g1]*delta[c1][d1]*delta[d0][g0] + delta[b0][g1]*delta[c1][g0]*delta[d0][d1]) + (PA_0*PQ[a1]*PQ[b1]*PQ[c1] + PA_0*PQ[a1]*PQ[b1]*QC_1 + PA_1*PQ[a0]*PQ[b1]*PQ[c1] + PA_1*PQ[a0]*PQ[b1]*QC_1 + PB_1*PQ[a0]*PQ[a1]*PQ[c1] + PB_1*PQ[a0]*PQ[a1]*QC_1 - PQ[a0]*PQ[a1]*PQ[b1]*PQ[c1] - PQ[a0]*PQ[a1]*PQ[b1]*QC_1)*(delta[b0][c0]*delta[d0][d1]*delta[g0][g1] + delta[b0][d0]*delta[c0][d1]*delta[g0][g1] + delta[b0][d1]*delta[c0][d0]*delta[g0][g1] + delta[b0][g0]*delta[c0][d0]*delta[d1][g1] + delta[b0][g0]*delta[c0][d1]*delta[d0][g1] + delta[b0][g0]*delta[c0][g1]*delta[d0][d1] + delta[b0][g1]*delta[c0][d0]*delta[d1][g0] + delta[b0][g1]*delta[c0][d1]*delta[d0][g0] + delta[b0][g1]*delta[c0][g0]*delta[d0][d1]) + (PA_0*PQ[a1]*PQ[b1]*PQ[d0] + PA_0*PQ[a1]*PQ[b1]*QD_0 + PA_1*PQ[a0]*PQ[b1]*PQ[d0] + PA_1*PQ[a0]*PQ[b1]*QD_0 + PB_1*PQ[a0]*PQ[a1]*PQ[d0] + PB_1*PQ[a0]*PQ[a1]*QD_0 - PQ[a0]*PQ[a1]*PQ[b1]*PQ[d0] - PQ[a0]*PQ[a1]*PQ[b1]*QD_0)*(delta[b0][c0]*delta[c1][d1]*delta[g0][g1] 