+ PQ[d0]*(QC_1*(delta[a0][d1]*delta[a1][g1] + delta[a0][g1]*delta[a1][d1]) + QD_1*(delta[a0][c1]*delta[a1][g1] + delta[a0][g1]*delta[a1][c1])) + PQ[d1]*(QC_1*(delta[a0][d0]*delta[a1][g1] + delta[a0][g1]*delta[a1][d0]) + QD_0*(delta[a0][c1]*delta[a1][g1] + delta[a0][g1]*delta[a1][c1]))) + PQ[g1]*(PQ[c1]*(QD_0*(delta[a0][d1]*delta[a1][g0] + delta[a0][g0]*delta[a1][d1]) + QD_1*(delta[a0][d0]*delta[a1][g0] + delta[a0][g0]*delta[a1][d0])) + PQ[d0]*(QC_1*(delta[a0][d1]*delta[a1][g0] + delta[a0][g0]*delta[a1][d1]) + QD_1*(delta[a0][c1]*delta[a1][g0] + delta[a0][g0]*delta[a1][c1])) + PQ[d1]*(QC_1*(delta[a0][d0]*delta[a1][g0] + delta[a0][g0]*delta[a1][d0]) + QD_0*(delta[a0][c1]*delta[a1][g0] + delta[a0][g0]*delta[a1][c1])))) + PQ[c1]*(PQ[d0]*(PQ[g0]*(QC_0*(delta[a0][d1]*delta[a1][g1] + delta[a0][g1]*delta[a1][d1]) + QD_1*(delta[a0][c0]*delta[a1][g1] + delta[a0][g1]*delta[a1][c0])) + PQ[g1]*(QC_0*(delta[a0][d1]*delta[a1][g0] + delta[a0][g0]*delta[a1][d1]) + QD_1*(delta[a0][c0]*delta[a1][g0] + delta[a0][g0]*delta[a1][c0]))) + PQ[d1]*(PQ[g0]*(QC_0*(delta[a0][d0]*delta[a1][g1] + delta[a0][g1]*delta[a1][d0]) + QD_0*(delta[a0][c0]*delta[a1][g1] + delta[a0][g1]*delta[a1][c0])) + PQ[g1]*(QC_0*(delta[a0][d0]*delta[a1][g0] + delta[a0][g0]*delta[a1][d0]) + QD_0*(delta[a0][c0]*delta[a1][g0] + delta[a0][g0]*delta[a1][c0]))))) + PQ[b0]*(PA_x*(PQ[c0]*(PQ[c1]*(QD_0*(delta[a0][d1]*delta[a1][g1] + delta[a0][g1]*delta[a1][d1]) + QD_1*(delta[a0][d0]*delta[a1][g1] + delta[a0][g1]*delta[a1][d0])) + PQ[d0]*(QC_1*(delta[a0][d1]*delta[a1][g1] + delta[a0][g1]*delta[a1][d1]) + QD_1*(delta[a0][c1]*delta[a1][g1] + delta[a0][g1]*delta[a1][c1])) + PQ[d1]*(QC_1*(delta[a0][d0]*delta[a1][g1] + delta[a0][g1]*delta[a1][d0]) + QD_0*(delta[a0][c1]*delta[a1][g1] + delta[a0][g1]*delta[a1][c1]))) + PQ[c1]*(PQ[d0]*(QC_0*(delta[a0][d1]*delta[a1][g1] + delta[a0][g1]*delta[a1][d1]) + QD_1*(delta[a0][c0]*delta[a1][g1] + delta[a0][g1]*delta[a1][c0])) + PQ[d1]*(QC_0*(delta[a0][d0]*delta[a1][g1] + delta[a0][g1]*delta[a1][d