elta[b0][c1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[b0][d1] + QD_1*delta[b0][c0]) + PQ[d1]*(QC_0*delta[b0][d0] + QD_0*delta[b0][c0]))) + PQ[b0]*(PQ[c0]*(PQ[c1]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + PQ[d0]*(QC_1*delta[a1][d1] + QD_1*delta[a1][c1]) + PQ[d1]*(QC_1*delta[a1][d0] + QD_0*delta[a1][c1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[a1][d1] + QD_1*delta[a1][c0]) + PQ[d1]*(QC_0*delta[a1][d0] + QD_0*delta[a1][c0]))))) + PQ[a1]*(PA_0*(PQ[b0]*(PQ[c0]*(PQ[c1]*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0]) + PQ[d0]*(QC_1*delta[b1][d1] + QD_1*delta[b1][c1]) + PQ[d1]*(QC_1*delta[b1][d0] + QD_0*delta[b1][c1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[b1][d1] + QD_1*delta[b1][c0]) + PQ[d1]*(QC_0*delta[b1][d0] + QD_0*delta[b1][c0]))) + PQ[b1]*(PQ[c0]*(PQ[c1]*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0]) + PQ[d0]*(QC_1*delta[b0][d1] + QD_1*delta[b0][c1]) + PQ[d1]*(QC_1*delta[b0][d0] + QD_0*delta[b0][c1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[b0][d1] + QD_1*delta[b0][c0]) + PQ[d1]*(QC_0*delta[b0][d0] + QD_0*delta[b0][c0])))) + (PB_0*PQ[b1] + PB_1*PQ[b0])*(PQ[c0]*(PQ[c1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + PQ[d0]*(QC_1*delta[a0][d1] + QD_1*delta[a0][c1]) + PQ[d1]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[a0][d1] + QD_1*delta[a0][c0]) + PQ[d1]*(QC_0*delta[a0][d0] + QD_0*delta[a0][c0])))) + PQ[b0]*PQ[b1]*(PA_0*(PQ[c0]*(PQ[c1]*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + PQ[d0]*(QC_1*delta[a1][d1] + QD_1*delta[a1][c1]) + PQ[d1]*(QC_1*delta[a1][d0] + QD_0*delta[a1][c1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[a1][d1] + QD_1*delta[a1][c0]) + PQ[d1]*(QC_0*delta[a1][d0] + QD_0*delta[a1][c0]))) + PA_1*(PQ[c0]*(PQ[c1]*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0]) + PQ[d0]*(QC_1*delta[a0][d1] + QD_1*delta[a0][c1]) + PQ[d1]*(QC_1*delta[a0][d0] + QD_0*delta[a0][c1])) + PQ[c1]*(PQ[d0]*(QC_0*delta[a0][d1] + QD_1*delta[a0][c0]) + PQ[d1]*(QC_0*delta[a0][d0] + QD_0*delta[a0][c0]))) + PQ[d0]*PQ[d1]*(PA_0*(QC_0*delta[a1][c1] + QC_1*delta[a1][c0]) + PA_1*(QC_0*delta[a0][c1] + QC_1*delta[a0][c0]))) + PQ[d0]*PQ[d1]*(PQ[a0]*(PA_1*(PQ[b0]*(QC_0*delta[b1][c1] + QC_1*delta[b1][c0]) + PQ[b1]*(QC_0*delta[b0][c1] + QC_1*delta[b0][c0])) + PB_0*(PQ[a1]*(QC_0*delta[b1][c1] + QC_1*delta[b1][c0]) + PQ[b1]*(QC_0*delta[a1][c1] + QC_1*delta[a1][c0])) + PB_1*(PQ[a1]*(QC_0*delta[b0][c1] + QC_1*delta[b0][c0]) + PQ[b0]*(QC_0*delta[a1][c1] + QC_1*delta[a1][c0]))) + PQ[a1]*(PA_0*(PQ[b0]*(QC_0*delta[b1][c1] + QC_1*delta[b1][c0]) + PQ[b1]*(QC_0*delta[b0][c1] + QC_1*delta[b0][c0])) + (PB_0*PQ[b1] + PB_1*PQ[b0])*(QC_0*delta[a0][c1] + QC_1*delta[a0][c0]))))

                            +(PQ[a0]*PQ[g1]*(PQ[a1]*PQ[g0]*(PB_0*PQ[b1] + PB_1*PQ[b0]) + PQ[b0]*PQ[b1]*(PA_1*PQ[g0] + PA_x*PQ[a1])) + PQ[a1]*PQ[b0]*PQ[b1]*PQ[g0]*(PA_0*PQ[g1] + PA_y*PQ[a0]))*(PQ[c0]*(delta[c1][d0]*(PQ[d1] + QD_1) + delta[c1][d1]*(PQ[d0] + QD_0) + delta[d0][d1]*(PQ[c1] + QC_1)) + PQ[c1]*(QC_0*delta[d0][d1] + delta[c0][d0]*(PQ[d1] + QD_1) + delta[c0][d1]*(PQ[d0] + QD_0)) + PQ[d0]*(QC_0*delta[c1][d1] + QC_1*delta[c0][d1] + delta[c0][c1]*(PQ[d1] + QD_1)) + PQ[d1]*(QC_0*delta[c1][d0] + QC_1*delta[c0][d0] + QD_0*delta[c0][c1]))

