            const auto rho = S1 * S2 * inv_S4;

            double d2 = 1.0;

            if (omega != 0.0) d2 = omega * omega / (rho + omega * omega);

            const auto Lambda = sqrt(4.0 * rho * d2 * MATH_CONST_INV_PI);

            double F10_t[2];

            gpu::computeBoysFunction(F10_t, rho * d2 * r2_PQ, 1, boys_func_table, boys_func_ft);

            if (omega != 0.0)
            {
                F10_t[1] *= d2;
            }

