                            -2*delta[d0][d1]*(delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0])*(PA_0*PA_1*(PB_0*PQ[b1] + PB_1*PQ[b0]) + PB_0*PB_1*(PA_0*PQ[a1] + PA_1*PQ[a0]))

