                            -PA_0*PA_1*(PB_0*(QD_0*(delta[b1][c0]*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + delta[b1][c1]*(delta[c0][d1]*delta[g0][g1] + delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0]) + delta[b1][g0]*(delta[c0][d1]*delta[c1][g1] + delta[c0][g1]*delta[c1][d1]) + delta[b1][g1]*(delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1])) + QD_1*(delta[b1][c0]*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + delta[b1][c1]*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0]) + delta[b1][g0]*(delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0]) + delta[b1][g1]*(delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0]))) + PB_1*(QD_0*(delta[b0][c0]*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + delta[b0][c1]*(delta[c0][d1]*delta[g0][g1] + delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0]) + delta[b0][g0]*(delta[c0][d1]*delta[c1][g1] + delta[c0][g1]*delta[c1][d1]) + delta[b0][g1]*(delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1])) + QD_1*(delta[b0][c0]*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + delta[b0][c1]*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0]) + delta[b0][g0]*(delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0]) + delta[b0][g1]*(delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0]))) + delta[c0][c1]*delta[g0][g1]*(PB_0*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0]) + PB_1*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0]))) - PB_0*PB_1*(PA_0*(QD_0*(delta[a1][c0]*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + delta[a1][c1]*(delta[c0][d1]*delta[g0][g1] + delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0]) + delta[a1][g0]*(delta[c0][d1]*delta[c1][g1] + delta[c0][g1]*delta[c1][d1]) + delta[a1][g1]*(delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1])) + QD_1*(delta[a1][c0]*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + delta[a1][c1]*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0]) + delta[a1][g0]*(delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0]) + delta[a1][g1]*(delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0]))) + PA_1*(QD_0*(delta[a0][c0]*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + delta[a0][c1]*(delta[c0][d1]*delta[g0][g1] + delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0]) + delta[a0][g0]*(delta[c0][d1]*delta[c1][g1] + delta[c0][g1]*delta[c1][d1]) + delta[a0][g1]*(delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1])) + QD_1*(delta[a0][c0]*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + delta[a0][c1]*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0]) + delta[a0][g0]*(delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0]) + delta[a0][g1]*(delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0]))) + delta[c0][c1]*delta[g0][g1]*(PA_0*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + PA_1*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0])))

                            -2*(delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0])*(PA_0*PA_1*(PB_0*(QD_0*delta[b1][d1] + QD_1*delta[b1][d0]) + PB_1*(QD_0*delta[b0][d1] + QD_1*delta[b0][d0])) + PB_0*PB_1*(PA_0*(QD_0*delta[a1][d1] + QD_1*delta[a1][d0]) + PA_1*(QD_0*delta[a0][d1] + QD_1*delta[a0][d0])))

                            -PA_0*PA_1*(PB_0*(QC_x*(delta[c0][g1]*(delta[b1][c1]*delta[d0][d1] + delta[b1][d0]*delta[c1][d1] + delta[b1][d1]*delta[c1][d0]) + delta[c1][g1]*(delta[b1][c0]*delta[d0][d1] + delta[b1][d0]*delta[c0][d1] + delta[b1][d1]*delta[c0][d0])) + QC_y*(delta[c0][g0]*(delta[b1][c1]*delta[d0][d1] + delta[b1][d0]*delta[c1][d1] + delta[b1][d1]*delta[c1][d0]) + delta[c1][g0]*(delta[b1][c0]*delta[d0][d1] + delta[b1][d0]*delta[c0][d1] + delta[b1][d1]*delta[c0][d0]))) + PB_1*(QC_x*(delta[c0][g1]*(delta[b0][c1]*delta[d0][d1] + delta[b0][d0]*delta[c1][d1] + delta[b0][d1]*delta[c1][d0]) + delta[c1][g1]*(delta[b0][c0]*delta[d0][d1] + delta[b0][d0]*delta[c0][d1] + delta[b0][d1]*delta[c0][d0])) + QC_y*(delta[c0][g0]*(delta[b0][c1]*delta[d0][d1] + delta[b0][d0]*delta[c1][d1] + delta[b0][d1]*delta[c1][d0]) + delta[c1][g0]*(delta[b0][c0]*delta[d0][d1] + delta[b0][d0]*delta[c0][d1] + delta[b0][d1]*delta[c0][d0])))) - PB_0*PB_1*(PA_0*(QC_x*(delta[c0][g1]*(delta[a1][c1]*delta[d0][d1] + delta[a1][d0]*delta[c1][d1] + delta[a1][d1]*delta[c1][d0]) + delta[c1][g1]*(delta[a1][c0]*delta[d0][d1] + delta[a1][d0]*delta[c0][d1] + delta[a1][d1]*delta[c0][d0])) + QC_y*(delta[c0][g0]*(delta[a1][c1]*delta[d0][d1] + delta[a1][d0]*delta[c1][d1] + delta[a1][d1]*delta[c1][d0]) + delta[c1][g0]*(delta[a1][c0]*delta[d0][d1] + delta[a1][d0]*delta[c0][d1] + delta[a1][d1]*delta[c0][d0]))) + PA_1*(QC_x*(delta[c0][g1]*(delta[a0][c1]*delta[d0][d1] + delta[a0][d0]*delta[c1][d1] + delta[a0][d1]*delta[c1][d0]) + delta[c1][g1]*(delta[a0][c0]*delta[d0][d1] + delta[a0][d0]*delta[c0][d1] + delta[a0][d1]*delta[c0][d0])) + QC_y*(delta[c0][g0]*(delta[a0][c1]*delta[d0][d1] + delta[a0][d0]*delta[c1][d1] + delta[a0][d1]*delta[c1][d0]) + delta[c1][g0]*(delta[a0][c0]*delta[d0][d1] + delta[a0][d0]*delta[c0][d1] + delta[a0][d1]*delta[c0][d0]))))

                            +(PA_0*(PA_1*delta[b0][b1] + PB_0*delta[a1][b1] + PB_1*delta[a1][b0]) + PA_1*(PB_0*delta[a0][b1] + PB_1*delta[a0][b0]) + PB_0*PB_1*delta[a0][a1])*(PQ[d0]*(QC_0*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + QC_1*(delta[c0][d1]*delta[g0][g1] + delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0])) + PQ[d1]*(QC_0*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + QC_1*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0])) + QD_0*((PQ[c0] + QC_0)*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + (PQ[c1] + QC_1)*(delta[c0][d1]*delta[g0][g1] + delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0])) + QD_1*((PQ[c0] + QC_0)*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + (PQ[c1] + QC_1)*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0])))

                            +(delta[c0][c1]*delta[g0][g1]*(PQ[d1]*QD_0 + QD_1*(PQ[d0] + QD_0)) + delta[d0][d1]*(QC_0*(PQ[c1]*delta[g0][g1] + PQ[g0]*delta[c1][g1] + PQ[g1]*delta[c1][g0]) + QC_1*(PQ[g0]*delta[c0][g1] + PQ[g1]*delta[c0][g0] + delta[g0][g1]*(PQ[c0] + QC_0)) + QC_x*(delta[c0][g1]*(PQ[c1] + QC_1) + delta[c1][g1]*(PQ[c0] + QC_0)) + QC_y*(delta[c0][g0]*(PQ[c1] + QC_1) + delta[c1][g0]*(PQ[c0] + QC_0))))*(PA_0*(PA_1*delta[b0][b1] + PB_0*delta[a1][b1] + PB_1*delta[a1][b0]) + PA_1*(PB_0*delta[a0][b1] + PB_1*delta[a0][b0]) + PB_0*PB_1*delta[a0][a1])

                            +2.0*(PQ[d1]*QD_0 + QD_1*(PQ[d0] + QD_0))*(delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0])*(PA_0*(PA_1*delta[b0][b1] + PB_0*delta[a1][b1] + PB_1*delta[a1][b0]) + PA_1*(PB_0*delta[a0][b1] + PB_1*delta[a0][b0]) + PB_0*PB_1*delta[a0][a1])

                            +(PA_0*(PA_1*delta[b0][b1] + PB_0*delta[a1][b1] + PB_1*delta[a1][b0]) + PA_1*(PB_0*delta[a0][b1] + PB_1*delta[a0][b0]) + PB_0*PB_1*delta[a0][a1])*(PQ[g0]*(QD_0*(delta[c0][d1]*delta[c1][g1] + delta[c0][g1]*delta[c1][d1]) + QD_1*(delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0])) + PQ[g1]*(QD_0*(delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1]) + QD_1*(delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0])) + QC_x*(delta[c0][g1]*(delta[c1][d0]*(PQ[d1] + QD_1) + delta[c1][d1]*(PQ[d0] + QD_0)) + delta[c1][g1]*(delta[c0][d0]*(PQ[d1] + QD_1) + delta[c0][d1]*(PQ[d0] + QD_0))) + QC_y*(delta[c0][g0]*(delta[c1][d0]*(PQ[d1] + QD_1) + delta[c1][d1]*(PQ[d0] + QD_0)) + delta[c1][g0]*(delta[c0][d0]*(PQ[d1] + QD_1) + delta[c0][d1]*(PQ[d0] + QD_0))))

                        )


                    );

            ERIs[threadIdx.y][threadIdx.x] -= eri_ijkl * mat_D_full_AO[j_cgto * naos + l_cgto];
        }
    }

    __syncthreads();

    if ((threadIdx.y == 0) && (threadIdx.x == 0) && (ik < pair_inds_count_for_K_dd))
    {
        double hess_kk_xy = 0.0;

        for (uint32_t y = 0; y < TILE_DIM_Y_K; y++)
        {
            for (uint32_t x = 0; x < TILE_DIM_X_K; x++)
            {
                hess_kk_xy += ERIs[y][x];
            }
        }

        atomicAdd(hess_xy + prim_cart_ao_to_atom_inds[s_prim_count + p_prim_count * 3 + k], hess_kk_xy * ik_factor_D * 2.0 * frac_exact_exchange);
    }
}

