                            +(PA_0*QC_x*QD_0*QD_1 - PQ[a0]*QC_x*QD_0*QD_1)*(delta[a1][b0]*delta[b1][c0]*delta[c1][g1] + delta[a1][b0]*delta[b1][c1]*delta[c0][g1] + delta[a1][b1]*delta[b0][c0]*delta[c1][g1] + delta[a1][b1]*delta[b0][c1]*delta[c0][g1] + delta[a1][c0]*delta[b0][b1]*delta[c1][g1] + delta[a1][c1]*delta[b0][b1]*delta[c0][g1]) + (PA_0*QC_y*QD_0*QD_1 - PQ[a0]*QC_y*QD_0*QD_1)*(delta[a1][b0]*delta[b1][c0]*delta[c1][g0] + delta[a1][b0]*delta[b1][c1]*delta[c0][g0] + delta[a1][b1]*delta[b0][c0]*delta[c1][g0] + delta[a1][b1]*delta[b0][c1]*delta[c0][g0] + delta[a1][c0]*delta[b0][b1]*delta[c1][g0] + delta[a1][c1]*delta[b0][b1]*delta[c0][g0]) + (PA_1*QC_x*QD_0*QD_1 - PQ[a1]*QC_x*QD_0*QD_1)*(delta[a0][b0]*delta[b1][c0]*delta[c1][g1] + delta[a0][b0]*delta[b1][c1]*delta[c0][g1] + delta[a0][b1]*delta[b0][c0]*delta[c1][g1] + delta[a0][b1]*delta[b0][c1]*delta[c0][g1] + delta[a0][c0]*delta[b0][b1]*delta[c1][g1] + delta[a0][c1]*delta[b0][b1]*delta[c0][g1]) + (PA_1*QC_y*QD_0*QD_1 - PQ[a1]*QC_y*QD_0*QD_1)*(delta[a0][b0]*delta[b1][c0]*delta[c1][g0] + delta[a0][b0]*delta[b1][c1]*delta[c0][g0] + delta[a0][b1]*delta[b0][c0]*delta[c1][g0] + delta[a0][b1]*delta[b0][c1]*delta[c0][g0] + delta[a0][c0]*delta[b0][b1]*delta[c1][g0] + delta[a0][c1]*delta[b0][b1]*delta[c0][g0]) + (PB_0*QC_x*QD_0*QD_1 - PQ[b0]*QC_x*QD_0*QD_1)*(delta[a0][a1]*delta[b1][c0]*delta[c1][g1] + delta[a0][a1]*delta[b1][c1]*delta[c0][g1] + delta[a0][b1]*delta[a1][c0]*delta[c1][g1] + delta[a0][b1]*delta[a1][c1]*delta[c0][g1] + delta[a0][c0]*delta[a1][b1]*delta[c1][g1] + delta[a0][c1]*delta[a1][b1]*delta[c0][g1]) + (PB_0*QC_y*QD_0*QD_1 - PQ[b0]*QC_y*QD_0*QD_1)*(delta[a0][a1]*delta[b1][c0]*delta[c1][g0] + delta[a0][a1]*delta[b1][c1]*delta[c0][g0] + delta[a0][b1]*delta[a1][c0]*delta[c1][g0] + delta[a0][b1]*delta[a1][c1]*delta[c0][g0] + delta[a0][c0]*delta[a1][b1]*delta[c1][g0] + delta[a0][c1]*delta[a1][b1]*delta[c0][g0]) + (PB_1*QC_x*QD_0*QD_1 - PQ[b1]*QC_x*QD_0*QD_1)*(delta[a0][a1]*delta[b0][c0]*delta[c1][g1] + delta[a0][a1]*delta[b0][c1]*delta[c0][g1] + delta[a0][b0]*delta[a1][c0]*delta[c1][g1] + delta[a0][b0]*delta[a1][c1]*delta[c0][g1] + delta[a0][c0]*delta[a1][b0]*delta[c1][g1] + delta[a0][c1]*delta[a1][b0]*delta[c0][g1]) + (PB_1*QC_y*QD_0*QD_1 - PQ[b1]*QC_y*QD_0*QD_1)*(delta[a0][a1]*delta[b0][c0]*delta[c1][g0] + delta[a0][a1]*delta[b0][c1]*delta[c0][g0] + delta[a0][b0]*delta[a1][c0]*delta[c1][g0] + delta[a0][b0]*delta[a1][c1]*delta[c0][g0] + delta[a0][c0]*delta[a1][b0]*delta[c1][g0] + delta[a0][c1]*delta[a1][b0]*delta[c0][g0])

