                            +(PQ[d0]*QC_x + PQ[g0]*QD_0)*(delta[a0][a1]*delta[b0][c0]*delta[b1][d1]*delta[c1][g1] + delta[a0][a1]*delta[b0][c1]*delta[b1][d1]*delta[c0][g1] + delta[a0][a1]*delta[b0][d1]*delta[b1][c0]*delta[c1][g1] + delta[a0][a1]*delta[b0][d1]*delta[b1][c1]*delta[c0][g1] + delta[a0][b0]*delta[a1][c0]*delta[b1][d1]*delta[c1][g1] + delta[a0][b0]*delta[a1][c1]*delta[b1][d1]*delta[c0][g1] + delta[a0][b0]*delta[a1][d1]*delta[b1][c0]*delta[c1][g1] + delta[a0][b0]*delta[a1][d1]*delta[b1][c1]*delta[c0][g1] + delta[a0][b1]*delta[a1][c0]*delta[b0][d1]*delta[c1][g1] + delta[a0][b1]*delta[a1][c1]*delta[b0][d1]*delta[c0][g1] + delta[a0][b1]*delta[a1][d1]*delta[b0][c0]*delta[c1][g1] + delta[a0][b1]*delta[a1][d1]*delta[b0][c1]*delta[c0][g1] + delta[a0][c0]*delta[a1][b0]*delta[b1][d1]*delta[c1][g1] + delta[a0][c0]*delta[a1][b1]*delta[b0][d1]*delta[c1][g1] + delta[a0][c0]*delta[a1][d1]*delta[b0][b1]*delta[c1][g1] + delta[a0][c1]*delta[a1][b0]*delta[b1][d1]*delta[c0][g1] + delta[a0][c1]*delta[a1][b1]*delta[b0][d1]*delta[c0][g1] + delta[a0][c1]*delta[a1][d1]*delta[b0][b1]*delta[c0][g1] + delta[a0][d1]*delta[a1][b0]*delta[b1][c0]*delta[c1][g1] + delta[a0][d1]*delta[a1][b0]*delta[b1][c1]*delta[c0][g1] + delta[a0][d1]*delta[a1][b1]*delta[b0][c0]*delta[c1][g1] + delta[a0][d1]*delta[a1][b1]*delta[b0][c1]*delta[c0][g1] + delta[a0][d1]*delta[a1][c0]*delta[b0][b1]*delta[c1][g1] + delta[a0][d1]*delta[a1][c1]*delta[b0][b1]*delta[c0][g1]) + (PQ[d0]*QC_y + PQ[g1]*QD_0)*(delta[a0][a1]*delta[b0][c0]*delta[b1][d1]*delta[c1][g0] + delta[a0][a1]*delta[b0][c1]*delta[b1][d1]*delta[c0][g0] + delta[a0][a1]*delta[b0][d1]*delta[b1][c0]*delta[c1][g0] + delta[a0][a1]*delta[b0][d1]*delta[b1][c1]*delta[c0][g0] + delta[a0][b0]*delta[a1][c0]*delta[b1][d1]*delta[c1][g0] + delta[a0][b0]*delta[a1][c1]*delta[b1][d1]*delta[c0][g0] + delta[a0][b0]*delta[a1][d1]*delta[b1][c0]*delta[c1][g0] + delta[a0][b0]*delta[a1][d1]*delta[b1][c1]*delta[c0][g0] + delta[a0][b1]*delta[a1][c0]*delta[b0][d1]*delta[c1][g0] 