                            +(delta[a0][a1]*delta[b0][b1] + delta[a0][b0]*delta[a1][b1] + delta[a0][b1]*delta[a1][b0])*(PQ[c0]*(PQ[c1]*(PQ[d0]*(delta[d1][g0]*(PQ[g1] + QC_y) + delta[d1][g1]*(PQ[g0] + QC_x) + delta[g0][g1]*(PQ[d1] + QD_1)) + PQ[d1]*(QD_0*delta[g0][g1] + delta[d0][g0]*(PQ[g1] + QC_y) + delta[d0][g1]*(PQ[g0] + QC_x)) + PQ[g0]*(QD_0*delta[d1][g1] + QD_1*delta[d0][g1] + delta[d0][d1]*(PQ[g1] + QC_y)) + PQ[g1]*(QC_x*delta[d0][d1] + QD_0*delta[d1][g0] + QD_1*delta[d0][g0])) + PQ[d0]*(PQ[g0]*(QC_1*delta[d1][g1] + QD_1*delta[c1][g1] + delta[c1][d1]*(PQ[g1] + QC_y)) + PQ[g1]*(QC_1*delta[d1][g0] + QC_x*delta[c1][d1] + QD_1*delta[c1][g0])) + PQ[d1]*(PQ[g0]*(QC_1*delta[d0][g1] + QD_0*delta[c1][g1] + delta[c1][d0]*(PQ[g1] + QC_y)) + PQ[g1]*(QC_1*delta[d0][g0] + QC_x*delta[c1][d0] + QD_0*delta[c1][g0]))) + PQ[c1]*(PQ[d0]*(PQ[g0]*(QC_0*delta[d1][g1] + QD_1*delta[c0][g1] + delta[c0][d1]*(PQ[g1] + QC_y)) + PQ[g1]*(QC_0*delta[d1][g0] + QC_x*delta[c0][d1] + QD_1*delta[c0][g0])) + PQ[d1]*(PQ[g0]*(QC_0*delta[d0][g1] + QD_0*delta[c0][g1] + delta[c0][d0]*(PQ[g1] + QC_y)) + PQ[g1]*(QC_0*delta[d0][g0] + QC_x*delta[c0][d0] + QD_0*delta[c0][g0]))) + PQ[d0]*PQ[d1]*(PQ[c0]*(QC_1*delta[g0][g1] + delta[c1][g0]*(PQ[g1] + QC_y) + delta[c1][g1]*(PQ[g0] + QC_x)) + PQ[c1]*(QC_0*delta[g0][g1] + delta[c0][g0]*(PQ[g1] + QC_y) + delta[c0][g1]*(PQ[g0] + QC_x)) + PQ[g0]*(QC_0*delta[c1][g1] + QC_1*delta[c0][g1] + delta[c0][c1]*(PQ[g1] + QC_y)) + PQ[g1]*(QC_0*delta[c1][g0] + QC_1*delta[c0][g0] + QC_x*delta[c0][c1])) + PQ[g0]*PQ[g1]*(PQ[c0]*(QC_1*delta[d0][d1] + QD_0*delta[c1][d1] + QD_1*delta[c1][d0]) + PQ[c1]*(QC_0*delta[d0][d1] + QD_0*delta[c0][d1] + QD_1*delta[c0][d0]) + PQ[d0]*(QC_0*delta[c1][d1] + QC_1*delta[c0][d1] + QD_1*delta[c0][c1]) + PQ[d1]*(QC_0*delta[c1][d0] + QC_1*delta[c0][d0] + QD_0*delta[c0][c1])))

