]*delta[b1][d0] + delta[a0][c0]*delta[a1][b1]*delta[b0][d0] + delta[a0][c0]*delta[a1][d0]*delta[b0][b1] + delta[a0][d0]*delta[a1][b0]*delta[b1][c0] + delta[a0][d0]*delta[a1][b1]*delta[b0][c0] + delta[a0][d0]*delta[a1][c0]*delta[b0][b1]) + PQ[d0]*PQ[d1]*PQ[g0]*PQ[g1]*(delta[a0][a1]*delta[b0][b1]*delta[c0][c1] + delta[a0][a1]*delta[b0][c0]*delta[b1][c1] + delta[a0][a1]*delta[b0][c1]*delta[b1][c0] + delta[a0][b0]*delta[a1][b1]*delta[c0][c1] + delta[a0][b0]*delta[a1][c0]*delta[b1][c1] + delta[a0][b0]*delta[a1][c1]*delta[b1][c0] + delta[a0][b1]*delta[a1][b0]*delta[c0][c1] + delta[a0][b1]*delta[a1][c0]*delta[b0][c1] + delta[a0][b1]*delta[a1][c1]*delta[b0][c0] + delta[a0][c0]*delta[a1][b0]*delta[b1][c1] + delta[a0][c0]*delta[a1][b1]*delta[b0][c1] + delta[a0][c0]*delta[a1][c1]*delta[b0][b1] + delta[a0][c1]*delta[a1][b0]*delta[b1][c0] + delta[a0][c1]*delta[a1][b1]*delta[b0][c0] + delta[a0][c1]*delta[a1][c0]*delta[b0][b1])

