                        + F10_t[7] * S1 * S1 * S1 * S2 * S2 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * inv_S4 * a_k * a_k * (

                            -PQ[a0]*PQ[a1]*PQ[b0]*PQ[b1]*(PQ[c0]*(2*PQ[c1]*(delta[d0][d1]*delta[g0][g1] + delta[d0][g0]*delta[d1][g1] + delta[d0][g1]*delta[d1][g0]) + 2*PQ[d0]*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + 2*PQ[d1]*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + 2*PQ[g0]*(delta[c1][d0]*delta[d1][g1] + delta[c1][d1]*delta[d0][g1] + delta[c1][g1]*delta[d0][d1]) + 2*PQ[g1]*(delta[c1][d0]*delta[d1][g0] + delta[c1][d1]*delta[d0][g0] + delta[c1][g0]*delta[d0][d1]) + QC_1*(delta[d0][d1]*delta[g0][g1] + delta[d0][g0]*delta[d1][g1] + delta[d0][g1]*delta[d1][g0]) + QC_x*(delta[c1][d0]*delta[d1][g1] + delta[c1][d1]*delta[d0][g1] + delta[c1][g1]*delta[d0][d1]) + QC_y*(delta[c1][d0]*delta[d1][g0] + delta[c1][d1]*delta[d0][g0] + delta[c1][g0]*delta[d0][d1]) + QD_0*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + QD_1*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0])) + PQ[c1]*(2*PQ[d0]*(delta[c0][d1]*delta[g0][g1] + delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0]) + 2*PQ[d1]*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0]) + 2*PQ[g0]*(delta[c0][d0]*delta[d1][g1] + delta[c0][d1]*delta[d0][g1] + delta[c0][g1]*delta[d0][d1]) + 2*PQ[g1]*(delta[c0][d0]*delta[d1][g0] + delta[c0][d1]*delta[d0][g0] + delta[c0][g0]*delta[d0][d1]) + QC_0*(delta[d0][d1]*delta[g0][g1] + delta[d0][g0]*delta[d1][g1] + delta[d0][g1]*delta[d1][g0]) + QC_x*(delta[c0][d0]*delta[d1][g1] + delta[c0][d1]*delta[d0][g1] + delta[c0][g1]*delta[d0][d1]) + QC_y*(delta[c0][d0]*delta[d1][g0] + delta[c0][d1]*delta[d0][g0] + delta[c0][g0]*delta[d0][d1]) + QD_0*(delta[c0][d1]*delta[g0][g1] + delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0]) + QD_1*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0])) + PQ[d0]*(2*PQ[d1]*(delta[c0][c1]*delta[g0][g1] + delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0]) + 2*PQ[g0]*(delta[c0][c1]*delta[d1][g1] + delta[c0][d1]*delta[c1][g1] + delta[c0][g1]*delta[c1][d1]) + 2*PQ[g1]*(delta[c0][c1]*delta[d1][g0] + delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1]) + QC_0*(delta[c1][d1]*delta[g0][g1] + delta[c1][g0]*delta[d1][g1] + delta[c1][g1]*delta[d1][g0]) + QC_1*(delta[c0][d1]*delta[g0][g1] + delta[c0][g0]*delta[d1][g1] + delta[c0][g1]*delta[d1][g0]) + QC_x*(delta[c0][c1]*delta[d1][g1] + delta[c0][d1]*delta[c1][g1] + delta[c0][g1]*delta[c1][d1]) + QC_y*(delta[c0][c1]*delta[d1][g0] + delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1]) + QD_1*(delta[c0][c1]*delta[g0][g1] + delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0])) + PQ[d1]*(QC_0*(delta[c1][d0]*delta[g0][g1] + delta[c1][g0]*delta[d0][g1] + delta[c1][g1]*delta[d0][g0]) + QC_1*(delta[c0][d0]*delta[g0][g1] + delta[c0][g0]*delta[d0][g1] + delta[c0][g1]*delta[d0][g0]) + QD_0*(delta[c0][c1]*delta[g0][g1] + delta[c0][g0]*delta[c1][g1] + delta[c0][g1]*delta[c1][g0]) + (2*PQ[g0] + QC_x)*(delta[c0][c1]*delta[d0][g1] + delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0]) + (2*PQ[g1] + QC_y)*(delta[c0][c1]*delta[d0][g0] + delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0])) + PQ[g0]*(QC_0*(delta[c1][d0]*delta[d1][g1] + delta[c1][d1]*delta[d0][g1] + delta[c1][g1]*delta[d0][d1]) + QC_1*(delta[c0][d0]*delta[d1][g1] + delta[c0][d1]*delta[d0][g1] + delta[c0][g1]*delta[d0][d1]) + QD_0*(delta[c0][c1]*delta[d1][g1] + delta[c0][d1]*delta[c1][g1] + delta[c0][g1]*delta[c1][d1]) + QD_1*(delta[c0][c1]*delta[d0][g1] + delta[c0][d0]*delta[c1][g1] + delta[c0][g1]*delta[c1][d0]) + (2*PQ[g1] + QC_y)*(delta[c0][c1]*delta[d0][d1] + delta[c0][d0]*delta[c1][d1] + delta[c0][d1]*delta[c1][d0])) + PQ[g1]*(QC_0*(delta[c1][d0]*delta[d1][g0] + delta[c1][d1]*delta[d0][g0] + delta[c1][g0]*delta[d0][d1]) + QC_1*(delta[c0][d0]*delta[d1][g0] + delta[c0][d1]*delta[d0][g0] + delta[c0][g0]*delta[d0][d1]) + QC_x*(delta[c0][c1]*delta[d0][d1] + delta[c0][d0]*delta[c1][d1] + delta[c0][d1]*delta[c1][d0]) + QD_0*(delta[c0][c1]*delta[d1][g0] + delta[c0][d1]*delta[c1][g0] + delta[c0][g0]*delta[c1][d1]) + QD_1*(delta[c0][c1]*delta[d0][g0] + delta[c0][d0]*delta[c1][g0] + delta[c0][g0]*delta[c1][d0])))

